@tool
extends Node

func run() -> Dictionary:
	var rep := {"quarantined": [], "moved": [], "deleted": [], "errors": []}
	var f := FileAccess.open("res://tools/gc_cleanup_ops.json", FileAccess.READ)
	if f == null:
		rep["errors"].append({"op": "startup", "src": "ops", "error": "ops file missing"})
		return rep
	var txt := f.get_as_text()
	f.close()
	var ops = JSON.parse_string(txt)
	if ops == null:
		rep["errors"].append({"op": "startup", "src": "ops", "error": "ops JSON parse failed"})
		return rep
	rep["errors"].append({"op": "info", "src": "ops", "error": "q=" + str(ops.get("quarantine", []).size()) + " m=" + str(ops.get("move", []).size()) + " d=" + str(ops.get("delete", []).size())})
	return rep
